SELECT b.*, COUNT(i.item_id) AS itemCount FROM EVAL_ASSIGN_BATCH b LEFT JOIN EVAL_ASSIGN_ITEM i ON b.batch_id = i.batch_id
AND b.status = #{status}
AND (b.batch_id LIKE CONCAT('%', #{keyword}, '%') OR b.create_by LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY b.batch_id ORDER BY b.create_time DESC LIMIT #{offset}, #{limit}

